    function updateProbeActivities() {
        const explore = parseInt(document.getElementById("explore-slider").value);
        const reproduce = parseInt(document.getElementById("reproduce-slider").value);
        const collectResources = parseInt(document.getElementById("collect-resources-slider").value);
        const total = explore + reproduce + collectResources;
        // Normalize to 100% allocation
        probes.forEach(probe => {
            probe.activity.explore = explore / total;
            probe.activity.reproduce = reproduce / total;
            probe.activity.collectResources = collectResources / total;
        });
    }
