  const strokeMaterial = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.8 });
  const strokeMesh = new THREE.Mesh(strokeGeometry, strokeMaterial);
  strokeMesh.name = 'likelihoodTextStroke';

  const textMesh = new THREE.Mesh(textGeometry, textMaterial);
  textMesh.name = 'likelihoodText';

  textGeometry.computeBoundingBox();
  const textWidth = textGeometry.boundingBox.max.x - textGeometry.boundingBox.min.x;
  textMesh.position.set(-textWidth / 2, 0, 0);
  strokeMesh.position.set(-textWidth / 2, 0, 0);

  scene.add(textMesh, strokeMesh);
}
